import {api} from './workspace-shared.js';
import {createClassAppearance} from './class-appearance.js';
export async function editClassPalette(classId,trigger){
 const data=await api('/api/classes/'+classId+'/palette'),dialog=document.createElement('dialog');dialog.className='class-palette-dialog';dialog.setAttribute('aria-label','Class colours');dialog.innerHTML='<form><header><h2></h2><button type="button" data-close-palette aria-label="Close class colours">×</button></header><div data-class-appearance></div><p data-palette-error role="alert"></p><button class="teacher-button" type="submit">Save class colours</button></form>';
 const form=dialog.querySelector('form'),error=dialog.querySelector('[data-palette-error]');dialog.querySelector('h2').textContent=data.className;const appearance=createClassAppearance({root:dialog.querySelector('[data-class-appearance]'),classId});appearance.fill(data.classPalette,classId);
 return new Promise(resolve=>{let result=null,busy=false;dialog.querySelector('[data-close-palette]').onclick=()=>{if(!busy)dialog.close();};dialog.oncancel=event=>{if(busy)event.preventDefault();};form.onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;form.querySelector('[type=submit]').disabled=true;error.textContent='';try{result=await api('/api/classes/'+classId+'/palette',{classPalette:appearance.value(),revision:data.revision,expectedUserId:data.userId});dialog.close();}catch(e){error.textContent=e.message;}finally{busy=false;form.querySelector('[type=submit]').disabled=false;}};dialog.onclose=()=>{appearance.destroy();dialog.remove();trigger?.focus();resolve(result);};document.body.append(dialog);dialog.showModal();});
}
